<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import WorkspaceLogin from '@/components/common/WorkspaceLogin.vue'
import { workspaceApi as api, workspaceToken, workspaceLogout, workspaceRequiresLogin, workspaceAccessReady, loadWorkspaceAccess, type KnowledgeBase, type KnowledgeDocument, type KnowledgeChunk, type StandardFaq, type SearchResult, type ImportPreview } from '@/services/workspace'
import { useAppStore } from '@/stores/app'
import '@/assets/workspace.css'

const router=useRouter(),store=useAppStore()
const bases=ref<KnowledgeBase[]>([]),baseId=ref<number|null>(null),documents=ref<KnowledgeDocument[]>([]),faqs=ref<StandardFaq[]>([]),chunks=ref<KnowledgeChunk[]>([])
const selectedDocId=ref<number|null>(null),selectedFaq=ref<StandardFaq|null>(null)
const tab=ref('faqs'),loading=ref(false),busy=ref(false),error=ref(''),keyword=ref(''),statusFilter=ref('ALL')
const modal=ref(''),file=ref<File|null>(null),editId=ref<number|null>(null),previousId=ref<number|undefined>()
const baseForm=reactive({name:'',description:'',campus:'',audience:'',chunkSize:800,overlap:100,chunkMode:'GENERAL'})
const textForm=reactive({title:'',source:'',content:'',effectiveAt:'',expiresAt:''})
const faqDefaults=()=>({question:'',aliases:'',answer:'',source:'',category:'校园服务',campus:'',audience:'',conditions:'',answerMode:'DIRECT',status:'DRAFT',effectiveAt:'',expiresAt:''})
const faqForm=reactive(faqDefaults()),chunkForm=reactive({id:0,content:'',enabled:true})
const size=ref(800),overlap=ref(100),preview=ref<{content:string;page?:number;section:string}[]>([])
const query=ref(''),queryCampus=ref(''),queryAudience=ref(''),result=ref<SearchResult|null>(null),importResult=ref<ImportPreview|null>(null)
const selectedBase=computed(()=>bases.value.find(b=>b.id===baseId.value))
const selectedDoc=computed(()=>documents.value.find(d=>d.id===selectedDocId.value))
const filteredFaqs=computed(()=>faqs.value.filter(f=>(`${f.question}${f.aliases??''}${f.answer}`.includes(keyword.value))&&(statusFilter.value==='ALL'||f.status===statusFilter.value)))
const filteredDocs=computed(()=>documents.value.filter(d=>`${d.title}${d.source??''}`.includes(keyword.value)))
const processing=computed(()=>documents.value.filter(d=>['QUEUED','PARSING'].includes(d.processing)).length)
const names:Record<string,string>={DRAFT:'草稿',PENDING:'待审核',PUBLISHED:'已发布',DISABLED:'已停用',ARCHIVED:'已归档',QUEUED:'排队中',PARSING:'解析中',AWAITING_CHUNKS:'待确认切片',READY:'全文就绪',FAILED:'处理失败',CANCELLED:'已取消',DIRECT:'快速直答',RAG:'模型组织',TOOL:'工具联动'}
function message(reason:unknown){return reason instanceof Error?reason.message:'请求失败'}
async function action(task:()=>Promise<unknown>,success?:string){if(busy.value)return;busy.value=true;error.value='';try{await task();if(success)store.notify(success)}catch(e){error.value=message(e);store.notify(error.value,'warning')}finally{busy.value=false}}
async function loadBases(){loading.value=true;error.value='';try{await loadWorkspaceAccess();if(workspaceRequiresLogin.value&&!workspaceToken.value)return;bases.value=await api.bases();if(!bases.value.some(b=>b.id===baseId.value))baseId.value=bases.value[0]?.id??null;if(baseId.value)await loadData()}catch(e){error.value=message(e)}finally{loading.value=false}}
async function loadData(){const id=baseId.value;if(!id)return;const [ds,fs]=await Promise.all([api.documents(id),api.faqs(id)]);if(id!==baseId.value)return;documents.value=ds;faqs.value=fs;selectedFaq.value=fs.find(f=>f.id===selectedFaq.value?.id)??fs[0]??null;if(!ds.some(d=>d.id===selectedDocId.value))selectedDocId.value=ds[0]?.id??null;if(selectedDocId.value)chunks.value=await api.chunks(selectedDocId.value)}
function openBase(edit=false){editId.value=edit?baseId.value:null;Object.assign(baseForm,edit&&selectedBase.value?selectedBase.value:{name:'',description:'',campus:'',audience:'',chunkSize:800,overlap:100,chunkMode:'GENERAL'});modal.value='base'}
function openText(){Object.assign(textForm,{title:'',source:'',content:'',effectiveAt:'',expiresAt:''});modal.value='text'}
function openUpload(prior?:number){file.value=null;previousId.value=prior;Object.assign(textForm,{title:'',source:'',content:'',effectiveAt:'',expiresAt:''});modal.value='upload'}
function openFaq(value?:StandardFaq){editId.value=value?.id??null;Object.assign(faqForm,faqDefaults(),value??{});modal.value='faq'}
async function saveBase(){await action(async()=>{const saved=await api.saveBase({...baseForm},editId.value??undefined);modal.value='';await loadBases();baseId.value=saved.id;await loadData()},'知识库配置已保存')}
async function saveText(){if(!baseId.value)return;await action(async()=>{const saved=await api.text(baseId.value!,{...textForm,effectiveAt:textForm.effectiveAt||null,expiresAt:textForm.expiresAt||null});modal.value='';await loadData();selectedDocId.value=saved.id;tab.value='chunks'},'文本已保存，请预览并确认切片')}
async function upload(){if(!baseId.value||!file.value)return;await action(async()=>{await api.upload(baseId.value!,file.value!,textForm.title,textForm.source,previousId.value);modal.value='';tab.value='documents';await loadData()},'文档已进入后台解析队列')}
async function saveFaq(){if(!baseId.value)return;await action(async()=>{const saved=await api.saveFaq(baseId.value!,{...faqForm,effectiveAt:faqForm.effectiveAt||null,expiresAt:faqForm.expiresAt||null},editId.value??undefined);modal.value='';await loadData();selectedFaq.value=saved},'问答已保存；发布时会检查重叠问法')}
async function documentAction(doc:KnowledgeDocument,kind:string){if(['ARCHIVE','DISABLE','PUBLISH'].includes(kind)&&!window.confirm(`确认${kind==='PUBLISH'?'发布':kind==='DISABLE'?'停用':'归档'}“${doc.title}”？`))return;await action(async()=>{await api.action(doc.id,kind);await loadData()},'文档状态已更新')}
async function migrate(){if(!baseId.value||!window.confirm('将尚未迁移的旧知识复制为文本草稿？旧数据不会被删除或覆盖。'))return;await action(async()=>{const r=await api.migrate(baseId.value!);await loadData();store.notify(`已迁移 ${r.imported} 条，请切片并审核发布`)})}
async function previewChunks(){if(!selectedDocId.value)return;await action(async()=>{preview.value=await api.preview(selectedDocId.value!,size.value,overlap.value)})}
async function commitChunks(){if(!selectedDocId.value)return;await action(async()=>{chunks.value=await api.split(selectedDocId.value!,size.value,overlap.value);preview.value=[];await loadData()},'切片已保存，全文检索可用；审核发布后参与问答')}
function openChunk(value:KnowledgeChunk){Object.assign(chunkForm,{id:value.id,content:value.content,enabled:value.enabled});modal.value='chunk'}
async function saveChunk(){await action(async()=>{await api.editChunk(chunkForm.id,chunkForm.content,chunkForm.enabled);modal.value='';await loadData()},'切片内容已更新')}
async function testSearch(){if(!baseId.value||!query.value.trim())return;result.value=null;await action(async()=>{result.value=await api.search(baseId.value!,query.value,queryCampus.value,queryAudience.value)})}
async function prepareImport(){if(!baseId.value||!file.value)return;await action(async()=>{importResult.value=await api.importPreview(baseId.value!,file.value!)})}
async function exportFaqs(){if(baseId.value)await action(()=>api.exportFaqs(baseId.value!))}
async function commitImport(){if(!baseId.value||!importResult.value||importResult.value.errors.length)return;await action(async()=>{const r=await api.importFaqs(baseId.value!,importResult.value!.rows);modal.value='';await loadData();store.notify(`已导入 ${r.imported} 条草稿，需人工审核`)})}
function pickFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;importResult.value=null}
watch(baseId,()=>{documents.value=[];faqs.value=[];chunks.value=[];selectedDocId.value=null;selectedFaq.value=null;preview.value=[];result.value=null;keyword.value='';const b=selectedBase.value;if(b){size.value=b.chunkSize;overlap.value=b.overlap;queryCampus.value=b.campus??'';queryAudience.value=b.audience??''}void action(loadData)})
watch(selectedDocId,async id=>{preview.value=[];chunks.value=[];if(id)try{const value=await api.chunks(id);if(id===selectedDocId.value)chunks.value=value}catch(e){error.value=message(e)}})
watch(workspaceToken,value=>{if(value)void loadBases();else{bases.value=[];documents.value=[];faqs.value=[]}})
const poll=window.setInterval(()=>{if((!workspaceRequiresLogin.value||workspaceToken.value)&&processing.value&&!busy.value)void loadData().catch(e=>{error.value=message(e)})},2000)
onMounted(loadBases);onUnmounted(()=>window.clearInterval(poll))
</script>

<template>
  <div v-if="!workspaceAccessReady" class="kw-page"><p v-if="error" class="kw-alert">{{ error }} <button class="kw-link" @click="loadBases">重试</button></p><p v-else class="kw-empty">正在连接工作台…</p></div>
  <WorkspaceLogin v-else-if="workspaceRequiresLogin&&!workspaceToken" @authenticated="loadBases" />
  <div v-else class="kw-page">
    <header class="kw-heading"><div><span class="kw-eyebrow">KNOWLEDGE WORKSPACE</span><h2>知识库与标准问答</h2><p>资料可追溯 · 文档切片 · 审核直答 · 检索测试</p></div><div class="kw-actions"><button class="btn" @click="router.push('/agents')">智能体工作台 ↗</button><button v-if="workspaceRequiresLogin" class="btn" @click="workspaceLogout">退出工作台</button></div></header>
    <p v-if="!workspaceRequiresLogin" class="kw-note">开发演示模式 · 局域网免登录，仅在可信 WiFi 下使用；请勿暴露到公网。</p>
    <p v-if="error" class="kw-alert" role="alert">{{ error }} <button class="kw-link" @click="loadBases">重新读取</button></p>
    <div class="kw-toolbar"><div class="kw-actions"><select v-model="baseId" class="select-input"><option v-if="!bases.length" :value="null">尚无知识库</option><option v-for="b in bases" :key="b.id" :value="b.id">{{ b.name }}</option></select><span class="kw-muted">{{ selectedBase?.description }}</span></div><div class="kw-actions"><button class="btn" @click="openBase()">＋ 新建知识库</button><button v-if="baseId" class="btn primary" @click="openUpload()">↑ 上传文档</button></div></div>
    <div v-if="loading" class="kw-empty">正在读取后端数据…</div>
    <section v-else-if="!baseId" class="panel kw-empty"><h3>创建第一个校园知识库</h3><p>文档、切片和问答会保存到 MySQL；此处不自动生成示例数据。</p><button class="btn primary" @click="openBase()">创建知识库</button></section>
    <template v-else>
      <div class="kw-stats"><article><span>知识文档</span><b>{{ documents.length }}</b><small>当前知识库全部版本</small></article><article><span>标准问答</span><b>{{ faqs.length }}</b><small>审核与来源独立管理</small></article><article><span>已发布问答</span><b>{{ faqs.filter(f=>f.status==='PUBLISHED').length }}</b><small>仍需符合有效期与适用范围</small></article><article><span>处理中 / 失败</span><b>{{ processing }} <em>/ {{ documents.filter(d=>d.processing==='FAILED').length }}</em></b><small>队列由后端持久化</small></article></div>
      <nav class="kw-tabs"><button v-for="t in [{id:'documents',label:'文档管理'},{id:'chunks',label:'切片管理'},{id:'faqs',label:'标准问答'},{id:'search',label:'检索测试'},{id:'settings',label:'知识库设置'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{ t.label }}</button></nav>

      <template v-if="tab==='documents'">
        <section class="panel kw-card"><div class="kw-section-head"><div><h3>文档与处理任务</h3><p>上传 → 解析 → 切片确认 → 审核发布；当前未执行OCR或向量索引</p></div><div class="kw-actions"><button class="btn" :disabled="busy" @click="migrate">迁移旧条目</button><button class="btn" @click="openText">录入文本</button><button class="btn" :disabled="busy" @click="action(loadData)">刷新</button></div></div><input v-model="keyword" class="filter-input" placeholder="搜索文档或来源"><div class="kw-table-scroll"><table class="data-table"><thead><tr><th>文档</th><th>处理状态</th><th>发布状态</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="doc in filteredDocs" :key="doc.id"><td><b>{{ doc.title }}</b><small class="kw-block">{{ doc.format }} · v{{ doc.versionNumber }} · {{ doc.fileSize?(doc.fileSize/1024).toFixed(1)+'KB':'文本来源' }}</small></td><td><span :class="['tag',doc.processing==='FAILED'?'red':doc.processing==='READY'?'green':'orange']">{{ names[doc.processing] }}</span><small v-if="doc.error" class="kw-error kw-block">{{ doc.error }}</small></td><td>{{ names[doc.status] }}</td><td>{{ doc.source||'待补充' }}</td><td><button class="kw-link" @click="selectedDocId=doc.id;tab='chunks'">查看切片</button><button v-if="doc.processing==='READY'&&doc.status!=='PUBLISHED'" class="kw-link" :disabled="busy" @click="documentAction(doc,'PUBLISH')">审核发布</button><button v-if="doc.status==='PUBLISHED'" class="kw-link" :disabled="busy" @click="documentAction(doc,'DISABLE')">停用</button><button v-if="doc.originalName" class="kw-link" @click="openUpload(doc.id)">新版本</button><button v-if="['FAILED','CANCELLED'].includes(doc.processing)" class="kw-link" :disabled="busy" @click="documentAction(doc,'RETRY')">重试</button><button v-if="['QUEUED','PARSING'].includes(doc.processing)" class="kw-link" :disabled="busy" @click="documentAction(doc,'CANCEL')">取消</button><button v-if="doc.status!=='ARCHIVED'" class="kw-link danger-text" :disabled="busy" @click="documentAction(doc,'ARCHIVE')">归档</button></td></tr><tr v-if="!filteredDocs.length"><td colspan="5" class="kw-empty">暂无文档，可上传文件或录入文本。</td></tr></tbody></table></div></section>
      </template>

      <template v-if="tab==='chunks'">
        <section class="panel kw-card"><div class="kw-section-head"><div><h3>原文与切片</h3><p>长度单位：字符。{{ selectedBase?.chunkMode==='PARENT_CHILD'?'父片保留章节，子片参与全文匹配。':'按段落与句子边界拆分。' }}</p></div><select v-model="selectedDocId" class="select-input"><option v-if="!documents.length" :value="null">请先导入文档</option><option v-for="d in documents" :key="d.id" :value="d.id">{{ d.title }} · v{{ d.versionNumber }}</option></select></div>
          <div class="kw-actions kw-wrap"><label>切片长度 <input v-model.number="size" class="kw-number" type="number" min="200" max="4000"></label><label>重叠字符 <input v-model.number="overlap" class="kw-number" type="number" min="0"></label><button class="btn" :disabled="busy||!selectedDoc?.content" @click="previewChunks">预览切片</button><button class="btn primary" :disabled="busy||!selectedDoc?.content||selectedDoc.status==='PUBLISHED'" @click="commitChunks">确认并生成全文切片</button><span class="tag">向量索引未接入</span></div>
          <p v-if="selectedDoc?.warning" class="kw-note">{{ selectedDoc.warning }}</p><p v-if="selectedDoc?.status==='PUBLISHED'" class="kw-note">已发布版本不能原地改动，请先停用或上传新版本。</p>
          <div class="kw-document-split"><article><h4>解析原文</h4><pre>{{ selectedDoc?.content||'文档尚未解析完成或尚未选择' }}</pre></article><article><h4>{{ preview.length?'预览（尚未保存）':'已保存切片' }} · {{ preview.length||chunks.length }}</h4><div class="kw-chunk-list"><div v-for="(piece,index) in preview" :key="'preview'+index" class="kw-chunk"><div><b>预览 {{ index+1 }}</b><span>{{ piece.content.length }} 字符</span></div><p>{{ piece.content }}</p></div><div v-for="piece in preview.length?[]:chunks" :key="piece.id" class="kw-chunk"><div><b>{{ piece.kind==='PARENT'?'父片':'子片' }} #{{ piece.id }}</b><span>{{ piece.page?'第'+piece.page+'页 · ':'' }}{{ piece.content.length }}字符</span></div><p>{{ piece.content }}</p><button class="kw-link" :disabled="selectedDoc?.status==='PUBLISHED'||!!piece.parentId||piece.kind==='PARENT'" @click="openChunk(piece)">编辑 / 启停</button><span v-if="!piece.enabled" class="tag orange">已停用</span></div><p v-if="!preview.length&&!chunks.length" class="kw-empty">选择参数后预览，确认后保存切片。</p></div></article></div>
        </section>
      </template>

      <div v-if="tab==='faqs'" class="kw-faq-layout">
        <section class="panel kw-card"><div class="kw-section-head"><div><h3>标准问答</h3><p>精确问法匹配可直答；含条件或工具需求时不直接结束任务</p></div><div class="kw-actions"><button class="btn" @click="file=null;importResult=null;modal='import'">批量导入</button><button class="btn" :disabled="busy" @click="exportFaqs">导出</button><button class="btn primary" @click="openFaq()">＋ 新增问答</button></div></div><div class="kw-actions"><input v-model="keyword" class="filter-input" placeholder="搜索问题、相似问法或答案"><select v-model="statusFilter" class="select-input"><option value="ALL">全部状态</option><option value="DRAFT">草稿</option><option value="PENDING">待审核</option><option value="PUBLISHED">已发布</option><option value="DISABLED">已停用</option></select></div><div class="kw-table-scroll"><table class="data-table"><thead><tr><th>标准问题</th><th>相似问法</th><th>回答模式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="f in filteredFaqs" :key="f.id" :class="{selected:selectedFaq?.id===f.id}" @click="selectedFaq=f"><td>{{ f.question }}<small class="kw-block">{{ f.updatedAt?.replace('T',' ').slice(0,16) }} · {{ f.expiresAt?'有效至 '+f.expiresAt:'未设到期日' }}</small></td><td>{{ f.aliases?.split(/[\n；;]/).filter(Boolean).length||0 }}种问法</td><td><span class="tag">{{ names[f.answerMode] }}</span></td><td><span :class="['tag',f.status==='PUBLISHED'?'green':'orange']">{{ names[f.status] }}</span></td><td><button class="kw-link" @click.stop="openFaq(f)">编辑</button></td></tr><tr v-if="!filteredFaqs.length"><td colspan="5" class="kw-empty">没有匹配问答，可手动新增或导入表格。</td></tr></tbody></table></div>
          <div v-if="selectedFaq" class="kw-faq-detail"><div class="kw-section-head"><h3>问答详情</h3><button class="kw-link" @click="openFaq(selectedFaq)">编辑问答</button></div><div class="kw-chips"><span v-for="alias in selectedFaq.aliases?.split(/[\n；;]/).filter(Boolean)" :key="alias">{{ alias }}</span></div><p class="kw-answer">{{ selectedFaq.answer }}</p><p class="kw-muted">来源：{{ selectedFaq.source||'待补充' }} · 校区：{{ selectedFaq.campus||'通用' }} · 人群：{{ selectedFaq.audience||'通用' }}</p><p v-if="selectedFaq.conditions" class="kw-note">适用条件：{{ selectedFaq.conditions }}（需确认条件，不自动直答）</p></div>
        </section>
        <aside class="panel kw-card"><h3>快速匹配测试</h3><p class="kw-muted">使用与智能体相同的问答匹配与全文检索服务。</p><textarea v-model="query" class="kw-textarea" rows="4" placeholder="输入学生的实际问法，例如：饭卡在哪领？"/><button class="btn primary kw-full" :disabled="busy||!query.trim()" @click="testSearch">{{ busy?'检索中…':'测试匹配' }}</button><div v-if="result" class="kw-test-result"><span :class="['tag',result.directAnswer?'green':'orange']">{{ result.directAnswer?'标准问答直接回答':'未达到精确直答条件' }}</span><p>{{ result.directAnswer||result.message }}</p><p class="kw-muted">生成模型调用：0次 · 中文全文 BM25</p><article v-for="hit in result.hits.slice(0,3)" :key="hit.id" class="kw-evidence"><b>{{ hit.title }}</b><small>{{ hit.id }} · BM25 {{ hit.score.toFixed(3) }}</small><p>{{ hit.content }}</p></article></div><div class="kw-next"><h4>接入校园智能体</h4><p>配置对话模型、系统提示词和发布版本，在工作台测试真实RAG。</p><button class="btn" @click="router.push('/agents')">进入工作台 ↗</button></div></aside>
      </div>

      <section v-if="tab==='search'" class="panel kw-card"><div class="kw-section-head"><div><h3>检索测试</h3><p>当前使用中文全文BM25；未配置向量与重排，不展示虚构的混合检索分数。</p></div><span class="tag">只检索已发布、有效、适用的内容</span></div><div class="kw-actions kw-wrap"><input v-model="query" class="filter-input kw-grow" placeholder="输入完整问题" @keyup.enter="testSearch"><input v-model="queryCampus" class="filter-input" placeholder="校区（与资料完全一致）"><input v-model="queryAudience" class="filter-input" placeholder="适用人群"><button class="btn primary" :disabled="busy||!query.trim()" @click="testSearch">检索</button></div><div v-if="result" class="kw-search-result"><p>{{ result.message }}</p><p v-if="result.directAnswer" class="kw-answer">{{ result.directAnswer }}</p><div v-for="hit in result.hits" :key="hit.id" class="kw-evidence"><div class="kw-section-head"><b>{{ hit.title }}</b><span class="tag">{{ hit.kind }} · BM25 {{ hit.score.toFixed(3) }}</span></div><small>{{ hit.id }} · {{ hit.page?'第'+hit.page+'页 · ':'' }}{{ hit.section||'标准问答' }} · {{ hit.version?'文档v'+hit.version:'' }}</small><p>{{ hit.content }}</p><small>来源：{{ hit.source||'待补充' }}</small></div><p v-if="!result.hits.length" class="kw-empty">没有符合条件的匹配片段，请检查发布状态、适用范围和文档内容。</p></div></section>
      <section v-if="tab==='settings'" class="panel kw-card"><h3>知识库设置</h3><p class="kw-muted">{{ selectedBase?.name }} · {{ selectedBase?.campus||'未限定校区' }} · {{ selectedBase?.audience||'未限定人群' }}</p><p>默认切片：{{ selectedBase?.chunkSize }}字符，重叠{{ selectedBase?.overlap }}字符，{{ selectedBase?.chunkMode==='PARENT_CHILD'?'父子模式':'通用模式' }}。</p><p class="kw-note">修改规则不会悄悄重建已发布文档。需要在文档页明确停用或创建新版本，再确认切片。</p><button class="btn primary" @click="openBase(true)">编辑知识库设置</button></section>
    </template>

    <div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal='')"><section class="modal kw-modal"><div class="modal-head"><h3>{{ ({base:'知识库配置',text:'录入文本',upload:previousId?'上传新版本':'上传文档',faq:'标准问答',import:'问答导入预览',chunk:'编辑切片'} as Record<string,string>)[modal] }}</h3><button class="modal-close" :disabled="busy" @click="modal=''">×</button></div><p v-if="error" class="kw-alert" role="alert">{{ error }}</p>
      <form v-if="modal==='base'" @submit.prevent="saveBase"><div class="modal-body form-grid"><label class="form-field full">知识库名称<input v-model="baseForm.name" required maxlength="100"></label><label class="form-field full">说明<textarea v-model="baseForm.description"/></label><label class="form-field">校区<input v-model="baseForm.campus" placeholder="留空表示不限定"></label><label class="form-field">适用人群<input v-model="baseForm.audience" placeholder="如：2026级本科新生"></label><label class="form-field">切片字符数<input v-model.number="baseForm.chunkSize" type="number" min="200" max="4000" required></label><label class="form-field">重叠字符数<input v-model.number="baseForm.overlap" type="number" min="0" required></label><label class="form-field full">切片模式<select v-model="baseForm.chunkMode"><option value="GENERAL">通用切片</option><option value="PARENT_CHILD">父子切片</option></select></label></div><div class="modal-foot"><button class="btn primary" :disabled="busy">保存知识库</button></div></form>
      <form v-if="modal==='text'||modal==='upload'" @submit.prevent="modal==='text'?saveText():upload()"><div class="modal-body form-grid"><label class="form-field full">标题<input v-model="textForm.title" :required="modal==='text'"></label><label class="form-field full">来源<input v-model="textForm.source" placeholder="填写发布部门或通知名称"></label><label v-if="modal==='upload'" class="form-field full">选择文件<input type="file" accept=".pdf,.docx,.md,.txt" required @change="pickFile"><small>最大15MB。扫描件需另行OCR；解析完成后先预览切片。</small></label><template v-else><label class="form-field full">正文<textarea v-model="textForm.content" rows="10" required/></label><label class="form-field">生效日期<input v-model="textForm.effectiveAt" type="date"></label><label class="form-field">到期日期<input v-model="textForm.expiresAt" type="date"></label></template></div><div class="modal-foot"><button class="btn primary" :disabled="busy">{{ busy?'保存中…':modal==='text'?'保存文本草稿':'上传并解析' }}</button></div></form>
      <form v-if="modal==='faq'" @submit.prevent="saveFaq"><div class="modal-body form-grid"><label class="form-field full">标准问题<input v-model="faqForm.question" required maxlength="255"></label><label class="form-field full">相似问法<textarea v-model="faqForm.aliases" rows="3" placeholder="每行一种问法；也可用分号分隔"/></label><label class="form-field full">标准答案<textarea v-model="faqForm.answer" rows="5" required/></label><label class="form-field">来源<input v-model="faqForm.source" :required="faqForm.status==='PUBLISHED'"></label><label class="form-field">分类<input v-model="faqForm.category"></label><label class="form-field">校区<input v-model="faqForm.campus"></label><label class="form-field">适用人群<input v-model="faqForm.audience"></label><label class="form-field full">前置条件 / 例外<textarea v-model="faqForm.conditions" placeholder="填写条件后需要澄清，不执行精确直答"/></label><label class="form-field">回答方式<select v-model="faqForm.answerMode"><option value="DIRECT">审核答案快速直答</option><option value="RAG">交给模型组织</option><option value="TOOL">需业务工具处理</option></select></label><label class="form-field">状态<select v-model="faqForm.status"><option value="DRAFT">草稿</option><option value="PENDING">待审核</option><option value="PUBLISHED">审核并发布</option><option value="DISABLED">停用</option></select></label><label class="form-field">生效日期<input v-model="faqForm.effectiveAt" type="date"></label><label class="form-field">到期日期<input v-model="faqForm.expiresAt" type="date"></label></div><div class="modal-foot"><button class="btn primary" :disabled="busy">保存问答</button></div></form>
      <div v-if="modal==='import'" class="modal-body"><p class="kw-muted">CSV或XLSX，最多1000条。列名：标准问题、相似问法、标准答案、来源。导入后全部为草稿。</p><input type="file" accept=".csv,.xlsx" @change="pickFile"><button class="btn" :disabled="busy||!file" @click="prepareImport">检查与预览</button><div v-if="importResult"><p>可解析 {{ importResult.rows.length }} 条，发现 {{ importResult.errors.length }} 个问题。</p><p v-for="issue in importResult.errors" :key="issue" class="kw-error">{{ issue }}</p><div v-for="(row,index) in importResult.rows.slice(0,8)" :key="index" class="kw-evidence"><b>{{ row.question }}</b><p>{{ row.answer }}</p></div><button class="btn primary" :disabled="busy||!!importResult.errors.length||!importResult.rows.length" @click="commitImport">确认导入草稿</button></div></div>
      <form v-if="modal==='chunk'" @submit.prevent="saveChunk"><div class="modal-body form-grid"><label class="form-field full">正文<textarea v-model="chunkForm.content" rows="12" maxlength="4000" required/></label><label><input v-model="chunkForm.enabled" type="checkbox">参与检索</label></div><div class="modal-foot"><button class="btn primary" :disabled="busy">保存切片</button></div></form>
    </section></div>
  </div>
</template>
